/**
 * Builds a worked-example run + report for the demo preset so the UI and the public report render without the
 * live engine. Everything here is honest: before/after verdicts are produced by the real @faultline/core checker;
 * patches are reference fixes (the real diff between the buggy and fixed rendered source), never AI patches, and are
 * not re-run: their "after" verdicts are the checker run on a constructed post-fix state; diagnoses are generated by the
 * real model when OLLAMA_API_KEY is set (labelled "AI explanation"), else the template (labelled "Template").
 *
 * It is labelled a worked example in the report; it is not presented as a live rehearsal measurement.
 */
import { randomUUID } from "node:crypto";
import { readFileSync } from "node:fs";
import { createPool, createDb } from "@faultline/db";
import { BUG_FOR_ATTACK, INVARIANT_TEXT, checkInvariants, getAttack, type AttackFacts, type TruthOrder } from "@faultline/core";
import type { CatalogItem, InvariantId, OrderStatus, ProbeState, Verdict } from "@faultline/schemas";
import { createOllama, diagnose } from "@faultline/agent";
import { renderVariant, parseBugList, diffFiles } from "@faultline/patch";

const url = process.env.DATABASE_URL;
if (!url) {
  console.error("DATABASE_URL is not set");
  process.exit(1);
}

const CATALOG: CatalogItem[] = [{ sku: "house-blend", name: "House Blend 250 g", price: "12.00", currency: "USD", creditsPerItem: 100 }];
const DEMO: Array<"A1" | "A3" | "A4" | "A5" | "A7"> = ["A1", "A3", "A4", "A5", "A7"];

type Scene = { store: OrderStatus; credits: number[]; paypal: "CREATED" | "APPROVED" | "COMPLETED"; captureId?: string | null; capturedAmount?: string; attempted?: boolean; sawError?: boolean };

const BEFORE: Record<string, Scene> = {
  A1: { store: "paid", credits: [100, 100, 100], paypal: "COMPLETED" },
  A3: { store: "paid", credits: [100], paypal: "CREATED", captureId: "FORGEDCAP", attempted: false },
  A4: { store: "failed", credits: [], paypal: "COMPLETED", captureId: null, attempted: true },
  A5: { store: "paid", credits: [100], paypal: "COMPLETED", capturedAmount: "0.01" },
  A7: { store: "paid", credits: [100], paypal: "APPROVED", attempted: true, sawError: false },
};
const AFTER: Record<string, Scene> = {
  A1: { store: "paid", credits: [100], paypal: "COMPLETED" },
  A3: { store: "created", credits: [], paypal: "CREATED", attempted: false },
  A4: { store: "paid", credits: [100], paypal: "COMPLETED" },
  A5: { store: "paid", credits: [100], paypal: "COMPLETED", capturedAmount: "12.00" },
  A7: { store: "failed", credits: [], paypal: "APPROVED", attempted: true, sawError: true },
};

function facts(attack: string, s: Scene): AttackFacts {
  const amount = s.capturedAmount ?? "12.00";
  const captures = s.paypal === "COMPLETED" ? [{ id: s.captureId ?? "3C6CAP0001", status: "COMPLETED", amount, currency: "USD" }] : [];
  const truth: TruthOrder = { id: "5OPP0001", status: s.paypal, amount: "12.00", currency: "USD", captures, evidenceId: "tr-0001" };
  const after: ProbeState = {
    storeTime: new Date().toISOString(),
    orders: [{ storeOrderId: "o_demo", paypalOrderId: "5OPP0001", sku: "house-blend", qty: 1, status: s.store, captureId: s.captureId === undefined ? (captures[0]?.id ?? null) : s.captureId, amount: "12.00", currency: "USD", updatedAt: new Date().toISOString() }],
    entitlements: s.credits.map((credits, i) => ({ storeOrderId: "o_demo", credits, source: "webhook" as const, grantedAt: new Date().toISOString(), ref: `WH-${i}` })),
    webhookEvents: [],
  };
  return {
    orderIds: ["5OPP0001"],
    truth: { "5OPP0001": truth },
    after,
    afterId: "st-0002",
    buyer: { captureAttempted: s.attempted ?? s.paypal !== "CREATED", sawError: s.sawError ?? false, evidenceId: "br-0003" },
    catalog: CATALOG,
    evidence: { webhooks: ["wf-0004"], captures: ["pc-0005"], creates: ["pc-0006"] },
  };
}

function referenceDiff(attack: string): string {
  const bug = BUG_FOR_ATTACK[attack as never];
  const files = ["src/routes/webhooks.ts", "src/routes/orders.ts", "src/db.ts"];
  const before: Record<string, string> = {};
  const after: Record<string, string> = {};
  for (const f of files) {
    const src = readFileSync(`apps/buggybeans/${f}`, "utf8");
    before[f] = renderVariant(src, parseBugList(bug));
    after[f] = renderVariant(src, parseBugList(""));
  }
  const diff = diffFiles(before, after);
  return diff || `--- a/src/routes/webhooks.ts\n+++ b/src/routes/webhooks.ts\n@@ reference fix @@\n (no textual change in the rendered demo slice)\n`;
}

async function main() {
  const pool = await createPool(url);
  const db = createDb(pool);
  const sql = pool;

  const target = await db.getTarget("buggybeans:demo");
  if (!target) {
    console.error("run `pnpm seed` first");
    process.exit(1);
  }

  // fresh run row (completed, agent), no job
  const runId = randomUUID();
  await sql.query(
    `insert into runs (id, target_id, session_id, mode, effective_mode, status, phase, budget, usage, allowed_attacks, model, prompt_version, summary, started_at, finished_at)
     values ($1,$2,null,'agent','agent','completed','done',$3::jsonb,$4::jsonb,$5,'gemma4:31b','2026-10-19',$6::jsonb, now(), now())`,
    [runId, target.id, JSON.stringify({ maxSteps: 20, maxAttacks: 8, maxPatchAttempts: 2, maxModelCalls: 40, maxSeconds: 900 }), JSON.stringify({ attacks: 5 }), DEMO, JSON.stringify({ headline: "Worked example — the checker flags 5 bugs on the demo preset (reference fixes, not re-run)", counts: { bugsProven: 5, aiFixed: 0, attacks: 5 } })],
  );

  const ollama = process.env.OLLAMA_API_KEY ? createOllama({ host: process.env.OLLAMA_HOST ?? "https://ollama.com", apiKey: process.env.OLLAMA_API_KEY, model: "gemma4:31b" }) : null;

  const reportFindings: unknown[] = [];
  let evCounter = 0;
  const ev = (kind: string, payload: Record<string, unknown>) => db.addEvent(runId, kind, payload);

  await ev("phase", { phase: "recon" });
  await ev("suspects", { summary: "Flagged 5 suspects from the store's payment code." });

  for (const attackId of DEMO) {
    const spec = getAttack(attackId);
    const beforeFacts = facts(attackId, BEFORE[attackId]!);
    const afterFacts = facts(attackId, AFTER[attackId]!);
    const beforeVerdicts = checkInvariants(spec.invariants, beforeFacts);
    const afterVerdicts = checkInvariants(spec.invariants, afterFacts);
    const failed = beforeVerdicts.filter((v) => v.status === "fail");

    const attackRowId = await db.createAttackRow({ runId, attackId, purpose: "baseline", spec });
    await db.finishAttackRow(attackRowId, { status: "done", instanceId: "demo", verdicts: beforeVerdicts, notes: null });
    await ev("attack_finished", { attackId, failed: failed.map((v) => v.invariant) });
    for (const id of ["br-0003", "pc-0005", "wf-0004", "tr-0001", "st-0002"]) await db.addTrace({ runId, evidenceId: id, attackRowId, kind: traceKind(id), at: new Date().toISOString(), summary: { attack: attackId, note: id.startsWith("wf") && (attackId === "A3") ? "forged by FaultLine" : undefined, injected: attackId === "A4" && id === "pc-0005" ? true : undefined }, detail: null });
    evCounter++;

    const finding = await db.createFinding({ runId, attackRowId, attackId, failedInvariants: failed.map((v) => v.invariant), verdicts: beforeVerdicts, evidence: [...new Set(failed.flatMap((v) => v.evidence))], severity: severityOf(failed) });

    const knownEvidence = new Set<string>(["br-0003", "pc-0005", "wf-0004", "tr-0001", "st-0002", "pc-0006", "src-0001", "src-0002"]);
    const trace = failed.map((v) => `${v.invariant}: expected ${v.expected}, actual ${v.actual} (${v.evidence.join(", ")})`).join("\n");
    const source = `<untrusted_source id="src-0001">${renderVariant(readFileSync(`apps/buggybeans/${affectedFile(attackId)}`, "utf8"), parseBugList(BUG_FOR_ATTACK[attackId as never])).slice(0, 1600)}</untrusted_source>`;
    let diag;
    if (ollama) {
      diag = await diagnose(ollama, { findingId: finding.id, attackId, verdicts: beforeVerdicts, trace, source, knownEvidence });
    } else {
      const { templateDiagnosis } = await import("@faultline/agent");
      diag = { source: "template" as const, body: templateDiagnosis({ findingId: finding.id, attackId, verdicts: beforeVerdicts, trace, source, knownEvidence }), evidenceValid: true, rawEvidenceValid: false };
    }
    await db.addDiagnosis({ findingId: finding.id, source: diag.source, body: diag.body, evidenceValid: diag.evidenceValid, rawEvidenceValid: diag.rawEvidenceValid });
    await ev("diagnosis", { attackId, source: diag.source, root_cause: diag.body.root_cause });

    const diff = referenceDiff(attackId);
    const patchId = await db.addPatch({ findingId: finding.id, attempt: 1, source: "reference", diff, guard: { passed: true, reasons: [] }, build: { passed: true }, status: "illustrative", verdicts: afterVerdicts });
    await db.updatePatch(patchId, { status: "illustrative", verdicts: afterVerdicts });
    await ev("patch", { attackId, status: "illustrative", source: "reference" });

    reportFindings.push({
      id: finding.id,
      attackId,
      title: titleOf(attackId, failed),
      severity: severityOf(failed),
      failedInvariants: failed.map((v) => v.invariant),
      verdicts: beforeVerdicts,
      diagnosis: { source: diag.source, body: diag.body, evidenceValid: diag.evidenceValid },
      patch: { attempt: 1, source: "reference", diff, guard: { passed: true, reasons: [] }, build: { passed: true }, status: "illustrative", verdicts: afterVerdicts, label: "Reference fix (not AI-generated)" },
    });
    console.log(`  ${attackId}: ${failed.map((v) => v.invariant).join(",")} fail → reference fix (not re-run) (diagnosis: ${diag.source})`);
  }

  await ev("phase", { phase: "done" });

  const slug = "demo" + Math.random().toString(36).slice(2, 8);
  const body = {
    slug,
    target: { name: target.name, slug: target.slug },
    mode: "agent",
    effectiveMode: "agent",
    model: "gemma4:31b",
    createdAt: new Date().toISOString(),
    usage: { attacks: 5 },
    summary: { headline: "Worked example — the checker flags 5 bugs on the demo preset (reference fixes, not re-run)", counts: { bugsProven: 5, aiFixed: 0, attacks: 5 } },
    findings: reportFindings,
    realVsSimulated: DEMO.map((a) => ({ attackId: a, text: getAttack(a).realVsSimulated })),
  };
  await db.createReport(runId, slug, body);
  await db.pinReport(runId);
  console.log(`seeded demo run ${runId} and pinned report /reports/${slug}`);
  void INVARIANT_TEXT;
  await pool.end();
}

function traceKind(id: string): "browser_step" | "paypal_call" | "webhook_forward" | "truth_read" | "state_snapshot" {
  return id.startsWith("br") ? "browser_step" : id.startsWith("pc") ? "paypal_call" : id.startsWith("wf") ? "webhook_forward" : id.startsWith("tr") ? "truth_read" : "state_snapshot";
}
function affectedFile(attackId: string): string {
  return ["A1", "A3"].includes(attackId) ? "src/routes/webhooks.ts" : "src/routes/orders.ts";
}
function severityOf(failed: Verdict[]): string {
  return failed.some((v) => ["I2", "I3", "I5", "I6", "I7"].includes(v.invariant as InvariantId)) ? "high" : "medium";
}
function titleOf(attackId: string, failed: Verdict[]): string {
  const map: Record<string, string> = {
    A1: "Credits granted three times for one purchase",
    A3: "A forged webhook granted credits for an unpaid order",
    A4: "Customer charged but received nothing after a capture timeout",
    A5: "A tampered price let the order complete for one cent",
    A7: "A declined payment was treated as a success",
  };
  return map[attackId] ?? `${attackId} failed ${failed.map((v) => v.invariant).join(", ")}`;
}

await main();
